using WinTools.Core.Files;
using WinTools.Worker.Imaging;

namespace WinTools.Worker.Tests;

/// <summary>
/// A deterministic, in-house compression corpus: images generated by code (no third-party or personal files), encoded
/// the way real files of each kind usually are. The content imitates what decides how well a file compresses:
/// smooth gradients and soft texture with some sharp edges and a little sensor noise for photographs, heavy fine
/// detail for high-ISO or foliage-like images, and flat colours with thin lines and glyph-like strokes for screenshots.
/// Sizes are moderate (about 2 MP) so the tests stay fast; the qualities follow common encoders: phones around 92–95 with
/// 4:2:0 chroma, cameras at 97 with 4:4:4, web images re-saved around 75.
/// </summary>
internal static class CompressionCorpus
{
    public const int Width = 1600, Height = 1200;

    public sealed record Sample(string Name, ImageFormat Format, byte[] Bytes, string Kind);

    public static IReadOnlyList<Sample> All() =>
    [
        new("phone.jpg", ImageFormat.Jpeg, WicCodec.Encode(Photo(11), ImageFormat.Jpeg, 0.93f), "phone-style photographic JPEG (q93, 4:2:0)"),
        new("camera.jpg", ImageFormat.Jpeg, WicCodec.Encode(Photo(12), ImageFormat.Jpeg, 0.97f, fullChroma: true), "high-quality camera-style JPEG (q97, 4:4:4)"),
        new("moderate.jpg", ImageFormat.Jpeg, WicCodec.Encode(Photo(13), ImageFormat.Jpeg, 0.75f), "JPEG already compressed at moderate quality (q75)"),
        new("noisy.jpg", ImageFormat.Jpeg, WicCodec.Encode(Noisy(14), ImageFormat.Jpeg, 0.92f), "noisy, detail-heavy JPEG (q92)"),
        new("screenshot.jpg", ImageFormat.Jpeg, WicCodec.Encode(Screenshot(15), ImageFormat.Jpeg, 0.95f), "screenshot saved as JPEG (q95)"),
        new("photo-lossy.webp", ImageFormat.WebP, SkiaCodec.EncodeWebP(Photo(16), 92, lossless: false), "lossy WebP photograph (q92)"),
        new("screenshot-lossless.webp", ImageFormat.WebP, SkiaCodec.EncodeWebP(Screenshot(17), 100, lossless: true), "lossless WebP screenshot"),
        new("unoptimized.png", ImageFormat.Png, PngStored(Screenshot(18)), "unoptimized PNG (stored, no zlib compression)"),
        new("optimized.png", ImageFormat.Png, SkiaCodec.EncodePngSmallest(Screenshot(19), PngStored(Screenshot(19))), "already optimized PNG (zlib 9, all filters)"),
    ];

    /// <summary>A landscape-like photograph: sky gradient, textured ground, a few sharp-edged objects, mild sensor noise.</summary>
    public static RasterImage Photo(int seed, int width = Width, int height = Height) => Render(width, height, seed, noiseSigma: 1.6, detail: 1.0);

    /// <summary>The same kind of scene with strong noise and fine detail (high ISO, foliage, gravel).</summary>
    public static RasterImage Noisy(int seed, int width = Width, int height = Height) => Render(width, height, seed, noiseSigma: 9, detail: 2.5);

    private static RasterImage Render(int w, int h, int seed, double noiseSigma, double detail)
    {
        var rnd = new Random(seed);
        var lattice = Enumerable.Range(0, 6).Select(_ => Lattice(rnd, 64)).ToArray();
        var objects = Enumerable.Range(0, 7).Select(_ => (X: rnd.NextDouble() * w, Y: h * (0.35 + rnd.NextDouble() * 0.6), R: 40 + rnd.NextDouble() * 180,
            C: (rnd.Next(30, 230), rnd.Next(30, 230), rnd.Next(30, 230)))).ToArray();
        var horizon = h * 0.42;
        var bgra = new byte[w * h * 4];
        for (var y = 0; y < h; y++)
            for (var x = 0; x < w; x++)
            {
                double r, g, b;
                if (y < horizon + 18 * Fbm(lattice[5], x / 300.0, 0, 2))
                {
                    var t = y / horizon; // sky: a smooth gradient with soft clouds
                    var cloud = Math.Max(0, Fbm(lattice[0], x / 220.0, y / 160.0, 4) - 0.1) * 160;
                    (r, g, b) = (90 + 70 * t + cloud, 140 + 50 * t + cloud, 210 + 20 * t + cloud * 0.8);
                }
                else
                {
                    var tex = Fbm(lattice[1], x / 90.0 * detail, y / 70.0 * detail, 5);
                    var fine = Fbm(lattice[2], x / 9.0 * detail, y / 9.0 * detail, 3);
                    (r, g, b) = (95 + 60 * tex + 25 * fine, 110 + 55 * tex + 22 * fine, 60 + 40 * tex + 15 * fine);
                }
                foreach (var o in objects)
                {
                    var dx = x - o.X; var dy = y - o.Y;
                    if (dx * dx + dy * dy * 1.8 < o.R * o.R)
                    {
                        var shade = 0.75 + 0.25 * Fbm(lattice[3], x / 40.0, y / 40.0, 3) - 0.25 * dy / o.R;
                        (r, g, b) = (o.C.Item1 * shade, o.C.Item2 * shade, o.C.Item3 * shade);
                    }
                }
                var i = (y * w + x) * 4;
                bgra[i] = Clamp(b + Gauss(rnd) * noiseSigma);
                bgra[i + 1] = Clamp(g + Gauss(rnd) * noiseSigma);
                bgra[i + 2] = Clamp(r + Gauss(rnd) * noiseSigma);
                bgra[i + 3] = 255;
            }
        return new RasterImage(w, h, bgra);
    }

    /// <summary>A desktop screenshot: flat panels, 1 px rules, coloured buttons and rows of glyph-like strokes.</summary>
    public static RasterImage Screenshot(int seed, int w = Width, int h = Height)
    {
        var rnd = new Random(seed);
        var bgra = new byte[w * h * 4];
        void Fill(int x0, int y0, int x1, int y1, (byte R, byte G, byte B) c)
        {
            for (var y = Math.Max(0, y0); y < Math.Min(h, y1); y++)
                for (var x = Math.Max(0, x0); x < Math.Min(w, x1); x++)
                {
                    var i = (y * w + x) * 4;
                    (bgra[i], bgra[i + 1], bgra[i + 2], bgra[i + 3]) = (c.B, c.G, c.R, 255);
                }
        }
        Fill(0, 0, w, h, (243, 243, 243));
        Fill(0, 0, w, 48, (32, 32, 36));          // title bar
        Fill(0, 48, 260, h, (230, 232, 236));     // side bar
        Fill(260, 48, 261, h, (200, 200, 205));   // rule
        for (var row = 0; row < 40; row++)
        {
            var y = 80 + row * 27;
            if (row % 2 == 0) Fill(261, y - 4, w, y + 19, (250, 250, 252));
            Fill(261, y + 22, w, y + 23, (225, 225, 228));
            // glyph-like strokes: words of 1–2 px vertical and horizontal bars
            var x = 290;
            while (x < w - 120)
            {
                var len = rnd.Next(3, 11);
                for (var k = 0; k < len; k++, x += 7)
                {
                    Fill(x, y + rnd.Next(0, 4), x + 1 + rnd.Next(2), y + 13, (40, 40, 48));
                    if (rnd.Next(3) == 0) Fill(x, y + 6, x + 5, y + 7, (40, 40, 48));
                }
                x += 9;
            }
            if (row % 7 == 3) Fill(w - 200, y - 2, w - 40, y + 18, ((byte)rnd.Next(20, 80), (byte)rnd.Next(100, 200), (byte)rnd.Next(150, 250)));
        }
        for (var i = 0; i < 10; i++) Fill(20, 80 + i * 36, 220, 104 + i * 36, i == 2 ? ((byte)34, (byte)197, (byte)94) : ((byte)214, (byte)216, (byte)222));
        return new RasterImage(w, h, bgra);
    }

    /// <summary>A PNG with stored (uncompressed) zlib blocks, as some tools write.</summary>
    public static byte[] PngStored(RasterImage image) =>
        PngWriter.Rgba(image.Width, image.Height, (x, y) =>
        {
            var i = (y * image.Width + x) * 4;
            return (image.Bgra[i + 2], image.Bgra[i + 1], image.Bgra[i], image.Bgra[i + 3]);
        }, System.IO.Compression.CompressionLevel.NoCompression);

    private static double[,] Lattice(Random rnd, int n)
    {
        var l = new double[n, n];
        for (var i = 0; i < n; i++) for (var j = 0; j < n; j++) l[i, j] = rnd.NextDouble() * 2 - 1;
        return l;
    }

    private static double Value(double[,] l, double x, double y)
    {
        var n = l.GetLength(0);
        var (xi, yi) = ((int)Math.Floor(x), (int)Math.Floor(y));
        var (fx, fy) = (x - xi, y - yi);
        fx = fx * fx * (3 - 2 * fx); fy = fy * fy * (3 - 2 * fy);
        double At(int a, int b) => l[((a % n) + n) % n, ((b % n) + n) % n];
        var top = At(xi, yi) + (At(xi + 1, yi) - At(xi, yi)) * fx;
        var bottom = At(xi, yi + 1) + (At(xi + 1, yi + 1) - At(xi, yi + 1)) * fx;
        return top + (bottom - top) * fy;
    }

    private static double Fbm(double[,] l, double x, double y, int octaves)
    {
        double sum = 0, amp = 0.5, freq = 1;
        for (var o = 0; o < octaves; o++) { sum += amp * Value(l, x * freq, y * freq); amp *= 0.5; freq *= 2.03; }
        return sum;
    }

    private static double Gauss(Random rnd) => Math.Sqrt(-2 * Math.Log(1 - rnd.NextDouble())) * Math.Cos(2 * Math.PI * rnd.NextDouble());

    private static byte Clamp(double v) => (byte)Math.Clamp((int)Math.Round(v), 0, 255);
}

/// <summary>
/// Structural similarity (SSIM) of the luma of two images, written independently of the product's own metric so the
/// tests do not grade the product with its own ruler: 8×8 windows on a 4-pixel grid, standard constants, mean over
/// windows. 1 means identical; around 0.99 is visually indistinguishable at normal viewing; below about 0.95 artefacts
/// become visible on close inspection.
/// </summary>
internal static class Ssim
{
    public static double Luma(RasterImage a, RasterImage b)
    {
        if (a.Width != b.Width || a.Height != b.Height) throw new ArgumentException("Sizes differ.");
        var (ya, yb) = (Y(a), Y(b));
        const double C1 = 6.5025, C2 = 58.5225; // (0.01·255)², (0.03·255)²
        double total = 0; var count = 0;
        for (var y0 = 0; y0 + 8 <= a.Height; y0 += 4)
            for (var x0 = 0; x0 + 8 <= a.Width; x0 += 4)
            {
                double sa = 0, sb = 0, saa = 0, sbb = 0, sab = 0;
                for (var y = y0; y < y0 + 8; y++)
                    for (var x = x0; x < x0 + 8; x++)
                    {
                        double p = ya[y * a.Width + x], q = yb[y * a.Width + x];
                        sa += p; sb += q; saa += p * p; sbb += q * q; sab += p * q;
                    }
                const double n = 64;
                var (ma, mb) = (sa / n, sb / n);
                var (va, vb, cov) = (saa / n - ma * ma, sbb / n - mb * mb, sab / n - ma * mb);
                total += (2 * ma * mb + C1) * (2 * cov + C2) / ((ma * ma + mb * mb + C1) * (va + vb + C2));
                count++;
            }
        return total / count;
    }

    private static float[] Y(RasterImage img)
    {
        var y = new float[img.Width * img.Height];
        for (var i = 0; i < y.Length; i++)
            y[i] = 0.114f * img.Bgra[i * 4] + 0.587f * img.Bgra[i * 4 + 1] + 0.299f * img.Bgra[i * 4 + 2];
        return y;
    }
}
